const SEARCHES = {
  indian_gold_prices: 'Search Indian Gold Prices',
  indian_silver_prices: 'Search Indian Silver Prices',
  gold_market: 'Search Global Gold News',
  silver_market: 'Search Global Silver News',
  fed_rates: 'Search Fed Interest Rates',
  us_dollar: 'Search US Dollar Moves',
  inflation: 'Search Inflation Indicators',
  central_banks: 'Search Central Bank Gold Buying',
  geopolitics: 'Search Geopolitical Risk',
  silver_industrial: 'Search Silver Industrial Demand',
  investment_demand: 'Search Investment Demand'
};
const now = DateTime.now().setZone('Asia/Kolkata').toFormat('dd LLL yyyy, HH:mm') + ' IST';
const clean = s => String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const toResults = json => {
  if (!json) return [];
  if (json.web && Array.isArray(json.web.results)) {
    const news = json.news && Array.isArray(json.news.results) ? json.news.results : [];
    return news.concat(json.web.results);
  }
  if (Array.isArray(json.results)) return json.results;
  if (json.url) return [json];
  return [];
};
const out = {};
const errors = [];
for (const key of Object.keys(SEARCHES)) {
  let items = [];
  try { items = $(SEARCHES[key]).all(); } catch (e) { errors.push(SEARCHES[key] + ': ' + e.message); }
  const rows = [];
  for (const it of items) {
    for (const r of toResults(it.json)) {
      rows.push({
        title: clean(r.title),
        url: r.url || '',
        published: clean(r.page_age || r.age || 'date not shown'),
        info: clean([r.description].concat(r.extra_snippets || []).join(' ')).slice(0, 500),
        search_time: now,
        topic: key
      });
    }
  }
  out[key] = rows.filter(r => r.url).slice(0, 10);
}
const pick = keys => keys.reduce((a, k) => a.concat(out[k] || []), []);
const seen = new Set();
const sources = [];
for (const k of Object.keys(out)) {
  for (const r of out[k]) {
    if (!seen.has(r.url)) { seen.add(r.url); sources.push({ title: r.title, url: r.url, published: r.published, topic: r.topic }); }
  }
}
return [{ json: {
  search_time: now,
  price_search_results: pick(['indian_gold_prices', 'indian_silver_prices']),
  gold_news: pick(['gold_market', 'central_banks', 'investment_demand']),
  silver_news: pick(['silver_market', 'silver_industrial', 'investment_demand']),
  economic_news: pick(['fed_rates', 'us_dollar', 'inflation']),
  geopolitical_news: pick(['geopolitics']),
  research_sources: sources,
  total_sources: sources.length,
  search_errors: errors
} }];

const real = items => items.filter(i => Object.keys(i.json).length > 0).map(i => i.json);
const events = real($('Load Historical Events').all()).filter(e => e.event);
const gold = real($('Load 20Y Gold Prices').all()).filter(r => r.metal);
const silver = real($('Load 20Y Silver Prices').all()).filter(r => r.metal);
const fmt = e => e.period + ' | ' + e.event + ' | metals: ' + e.metals + ' | ' + e.movement + ' | ' + e.description + ' | source: ' + e.source;
return [{ json: {
  gold_price_history_status: gold.length ? 'AVAILABLE (' + gold.length + ' rows)' : 'PENDING - 20-year gold price series not loaded yet',
  silver_price_history_status: silver.length ? 'AVAILABLE (' + silver.length + ' rows)' : 'PENDING - 20-year silver price series not loaded yet',
  historical_events_status: events.length ? 'PARTIAL - ' + events.length + ' user-provided events (not independently verified)' : 'PENDING - no historical events stored',
  historical_news_status: 'PENDING - historical news archive not connected yet',
  price_spikes: events.filter(e => /spike|rise/.test(e.movement)).map(fmt),
  price_drops: events.filter(e => /drop|weak/.test(e.movement)).map(fmt),
  recovery_periods: events.filter(e => e.movement === 'recovery').map(fmt),
  historical_events_text: events.length ? events.map(fmt).join('\n') : 'None available',
  price_history_available: gold.length > 0 && silver.length > 0
} }];

