const j = $input.first().json;
let r = j.structuredOutput;
if (!r || typeof r !== 'object') {
  try { const m = String(j.text || '').match(/\{[\s\S]*\}/); r = m ? JSON.parse(m[0]) : null; } catch (e) { r = null; }
}
if (!r) {
  return [{ json: { validation_status: 'FAILED - Judge did not return structured predictions', prediction_table: 'Not available', validation_warnings: ['No structured output from Judge'], report_markdown: j.text || '', sources: [] } }];
}
const warnings = [];
const preds = Array.isArray(r.predictions) ? r.predictions : [];
const expected = ['gold|1 year', 'gold|3 years', 'gold|5 years', 'silver|1 year', 'silver|3 years', 'silver|5 years'];
const have = preds.map(p => p.metal + '|' + p.horizon);
for (const e of expected) if (!have.includes(e)) warnings.push('Missing prediction: ' + e.replace('|', ' '));
const isNum = v => typeof v === 'number' && !isNaN(v);
for (const p of preds) {
  const label = p.metal + ' ' + p.horizon;
  const vals = [p.bullish_pct, p.bearish_pct, p.sideways_pct];
  if (vals.every(isNum)) {
    const sum = vals.reduce((a, b) => a + b, 0);
    if (Math.abs(sum - 100) > 2) warnings.push(label + ': probabilities sum to ' + sum + '%, not 100%');
  } else {
    warnings.push(label + ': insufficient evidence - probabilities not estimated');
  }
  if (!['BUY', 'WAIT', 'AVOID'].includes(p.recommendation)) warnings.push(label + ': invalid recommendation ' + p.recommendation);
}
const pct = v => isNum(v) ? v + '%' : 'Insufficient evidence';
const header = '| Metal | Horizon | Bullish | Bearish | Sideways | BUY suitability | Recommendation | Confidence | Evidence |\n|---|---|---|---|---|---|---|---|---|';
const rows = preds.map(p => '| ' + p.metal + ' | ' + p.horizon + ' | ' + pct(p.bullish_pct) + ' | ' + pct(p.bearish_pct) + ' | ' + pct(p.sideways_pct) + ' | ' + pct(p.buy_suitability_pct) + ' | ' + p.recommendation + ' | ' + pct(p.confidence_pct) + ' | ' + p.evidence_strength + ' |');
return [{ json: {
  validation_status: warnings.some(w => !/insufficient evidence/.test(w)) ? 'CHECK WARNINGS' : 'OK',
  validation_warnings: warnings,
  prediction_table: [header].concat(rows).join('\n'),
  predictions: preds,
  current_prices: r.current_prices,
  international_situation: r.international_situation,
  bull_summary: r.bull_summary,
  bear_summary: r.bear_summary,
  analyst_comparison: r.analyst_comparison,
  historical_comparison: r.historical_comparison,
  key_risks: r.key_risks,
  sources: r.sources || [],
  report_markdown: r.report_markdown || ''
} }];
